import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { ModalController } from '@ionic/angular';
import { AlertService } from 'src/app/services/alert.service';
import { UserService } from 'src/app/services/emis/user.service';
import { UserSessionService } from 'src/app/services/usersession.service';
import { MhtViewModalPage } from '../../mht/mht-view-modal/mht-view-modal.page';
import { MyPatientViewModalPage } from '../my-patient-view-modal/my-patient-view-modal.page';
import { SummarypopuppagePage } from '../../commonpages/summarypopuppage/summarypopuppage.page';

@Component({
  selector: 'app-deic-referred-page',
  templateUrl: './deic-referred-page.page.html',
  styleUrls: ['./deic-referred-page.page.scss'],
})
export class DeicReferredPagePage implements OnInit {
  referralData: any;
  UserName: any;
  expandedIndex: number | null = null;
  acYear: string = '2024-25';
  flag: string = '2';
  myPatientViewType: any;
  status_of_child: any ;
  PhaseId: any;
  mhtOrAwc: any = 'mht';
  constructor(private router: Router,private alert: AlertService, 
    private userService: UserService, private alertService: AlertService, 
    private usersessionService: UserSessionService, private modalCtrl:ModalController) { }

  ngOnInit() {
  }
  
  ionViewDidEnter() {
    debugger
    this.UserName = this.usersessionService.emis_username();
    var checkMyPatientViewType = localStorage.getItem('myPatientViewType');
    if(checkMyPatientViewType && checkMyPatientViewType != undefined){
      this.myPatientViewType = JSON.parse(checkMyPatientViewType);
      this.fetchReferralData()
    }
    else{
      this.schoolAlert();
    }
  }

  onGoButton() {
    this.router.navigate(['/tabs/home'])
  }

  fetchReferralData() {
    this.PhaseId = (this.flag == "1" && this.acYear === "2023-24") ? ["1", "2"] : 
          (this.flag == "1" && this.acYear === "2024-25") ?  ["3","4"] : null ;
    if(this.myPatientViewType?.type != 2 && this.myPatientViewType?.diagnosis?.length === 0){
      this.userService.getDiagnosis(this.myPatientViewType.type).subscribe((res)=>{
        if (res.dataStatus) {
          this.myPatientViewType.diagnosis = res.result;
        }
        var data={
          records:{
          "type": this.myPatientViewType?.type ? this.myPatientViewType?.type : 2,
          "diagnosis": this.myPatientViewType?.diagnosis,
          "userName":this.UserName,
          "acYear":this.acYear,
          "phaseId": this.PhaseId,
          "flag":this.flag
          }
        };
        this.userService.getDEICStudents(data).subscribe((res) => {
          if(res.result){
            this.referralData= res.result
          }
          else {
            this.referralData=[]
            this.alertService.warning('No data found');
          }
        })
      
      })
    }
    else{
      var data={
        records:{
        "type": this.myPatientViewType?.type ? this.myPatientViewType?.type : 2,
        "diagnosis": this.myPatientViewType?.diagnosis?.map(item => item.value),
        "userName":this.UserName,
        "acYear":this.acYear,
        "phaseId": this.PhaseId ,
        "flag":this.flag
        }
      };
      if(this.myPatientViewType?.type != 2){

        this.userService.getDEICStudents(data).subscribe((res) => {
          if(res.result){
            this.referralData= res.result
          }
          else {
            this.referralData=[]
            this.alertService.warning('No data found');
          }
        })
      }
      else{
        var data={
          records:{
          "type": this.myPatientViewType?.type ? this.myPatientViewType?.type : 2,
          "diagnosis": this.myPatientViewType?.diagnosis?.map(item => item.value),
          "userName":this.UserName,
          "acYear":this.acYear,
          "phaseId": this.PhaseId ,
          "flag":this.flag
          }
        };
        this.userService.getDEICStudents(data).subscribe((res) => {
          if(res.result){
            this.referralData= res.result
          }
          else {
            this.referralData=[]
            this.alertService.warning('No data found');
          }
        })
      }
    }
  }
  
  async schoolAlert() {
    const modal = await this.modalCtrl.create({
      component: MyPatientViewModalPage,
      componentProps: {mhtOrAwc: this.mhtOrAwc },
      cssClass: 'fullscreen'
    });
    await modal.present();

    const { data } = await modal.onDidDismiss();
    this.handleModalClose(data);
  }

  handleModalClose(data){
    if(data && data != undefined){
      this.myPatientViewType = data;
      localStorage.removeItem('myPatientViewType');
      localStorage.setItem('myPatientViewType', JSON.stringify(data));
      this.fetchReferralData()
    }
  }

  toggleDetails(index: number) {
    this.expandedIndex = this.expandedIndex === index ? null : index;
  }

  onSelect(selectedValue: string){
    this.acYear = selectedValue;
    this.fetchReferralData()
  }

  onTreatmentSelect(item,selectedValue){
    let params = 
    {
      "records": {
          "generalId":item.general_id,
          "studId":item.id,
          "rbskRemarks":selectedValue,
          "updatedBy":this.UserName
      }
    }

    this.userService.postDEICUpdateTreatmentStatus(params).subscribe((res) => {
      console.log(res);
      if(res.message){
        console.log("inside");
        this.alertService.warning(res.message);
      }
      else {
        this.alertService.warning('Unable to update data');
      }
    })


  }

  onTypeSelect(flagging: string){
    localStorage.removeItem('myPatientViewType');
    localStorage.setItem('myPatientViewType', JSON.stringify({"type":"2","diagnosis":[]}));
    var checkMyPatientViewType = localStorage.getItem('myPatientViewType');
    this.myPatientViewType = JSON.parse(checkMyPatientViewType);
    if(flagging==='1'){
      this.mhtOrAwc = 'Awc'
    }
    else{
      this.mhtOrAwc = 'mht'
    }
    this.flag = flagging;
    this.fetchReferralData();
    
  }

  async openVisitStatusModal(record){
    console.log("inside");
        this.userService.getDEICgetVisitedDate(record.id,this.flag).subscribe(async (res) => {
                  if (res.result) {
                    const modal = await this.modalCtrl.create({
                      component: SummarypopuppagePage,
                      componentProps: {
                        schoolname:record.Name,
                        reportname:'Visit report',
                        items: res.result.map(item => ({
                          date: item.visited_date,
                          date_ts: item.visited_date,
                        }))
                      },
                      cssClass: 'view-image-modal_capturedimage',
                      backdropDismiss: true,
                    });
                    await modal.present();
                  }
                  else {
                    this.alert.error('No data found');
                  }
                });
      }
}
